const envelope = $json;

if (!envelope || envelope.success !== true) {
  throw new Error(
    'A API não confirmou a reserva do job visual.'
  );
}

if (envelope.empty || !envelope.data) {
  return [];
}

const data = envelope.data;

if (
  !data.job?.id ||
  !data.channel?.id ||
  !data.format?.key ||
  !data.approved_copy?.content
) {
  throw new Error(
    'O job visual reservado está incompleto.'
  );
}

return [{ json: data }];

const data = $json;
const format = data.format;
const campaign = data.campaign || {};
const channel = data.channel || {};
const product = data.product || {};
const brand = data.brand_profile || {};
const copy = data.approved_copy?.content || {};

const sizes = {
  square: '1024x1024',
  feed_portrait: '1024x1536',
  story: '1024x1536',
  landscape: '1536x1024'
};

const formatNames = {
  square: 'post quadrado',
  feed_portrait: 'post vertical do feed',
  story: 'Story ou Reels vertical',
  landscape: 'anúncio horizontal'
};

const media = Array.isArray(data.product_media)
  ? data.product_media
  : [];

const referenceUrls = [
  ...new Set(
    media
      .map(item => String(item.public_url || '').trim())
      .filter(url => /^https:\/\//i.test(url))
  )
].slice(0, 3);

const includePrice =
  Boolean(campaign.include_price) &&
  product.sale_price !== null &&
  product.sale_price !== undefined;

const price = includePrice
  ? Number(product.sale_price)
      .toLocaleString(
        'pt-BR',
        {
          style: 'currency',
          currency: 'BRL'
        }
      )
  : null;

const prompt = [
  'Crie uma peça publicitária premium para a Miranda Express.',
  'Formato de uso: ' +
    (formatNames[format.key] || format.key) + '.',
  'Dimensão final esperada: ' +
    format.width + 'x' + format.height + '.',
  'Use as imagens fornecidas como referência obrigatória do produto real.',
  'Preserve fielmente formato, cor, conectores, embalagem, marca e acessórios visíveis.',
  'Não invente outro modelo, portas, selos, certificações ou acessórios.',
  'Composição elegante de loja premium, fundo escuro sofisticado com detalhes dourados discretos.',
  'Produto grande, nítido, bem iluminado e totalmente dentro da área segura.',
  'Deixe margens amplas para evitar cortes no celular.',
  'Não use logotipos de fabricantes que não apareçam na foto real.',
  'Não escreva textos pequenos ou parágrafos longos na imagem.',
  'Não mencione original, oficial, réplica ou similar.',
  product.name
    ? 'Produto: ' + product.name + '.'
    : '',
  product.description
    ? 'Descrição confirmada: ' + product.description + '.'
    : '',
  copy.headline
    ? 'Título comercial sugerido: ' + copy.headline + '.'
    : '',
  copy.cta
    ? 'CTA curto: ' + copy.cta + '.'
    : '',
  price
    ? 'Preço confirmado que pode aparecer: ' + price + '.'
    : 'Não coloque preço.',
  brand.primary_color
    ? 'Cor principal da marca: ' +
      brand.primary_color + '.'
    : '',
  'O resultado precisa parecer fotografia publicitária profissional, não desenho.',
  'Evite mãos deformadas, cabos tortos, conectores incorretos e textos ilegíveis.'
].filter(Boolean).join('\n');

const content = [
  {
    type: 'input_text',
    text: prompt
  },
  ...referenceUrls.map(url => ({
    type: 'input_image',
    image_url: url,
    detail: 'high'
  }))
];

return [{
  json: {
    ...data,
    worker_id:
      'n8n-central-criativos-imagens-v1',
    image_prompt: prompt,
    reference_urls: referenceUrls,
    openai_request: {
      model: 'gpt-5.4',
      input: [{
        role: 'user',
        content
      }],
      tools: [{
        type: 'image_generation',
        quality: 'high',
        size: sizes[format.key] || '1024x1024'
      }]
    }
  }
}];

const source =
  $('Preparar Criativo Visual').first().json;

const response = $json;

const calls = Array.isArray(response.output)
  ? response.output.filter(
      item =>
        item &&
        item.type === 'image_generation_call' &&
        typeof item.result === 'string'
    )
  : [];

if (!calls.length) {
  const message =
    response.error?.message ||
    response.output_text ||
    'A OpenAI não retornou uma imagem.';

  throw new Error(message);
}

const imageBase64 = calls[0].result;

if (imageBase64.length < 100) {
  throw new Error(
    'A imagem retornada está vazia ou inválida.'
  );
}

return [{
  json: {
    job_id: source.job.id,
    worker_id: source.worker_id,
    channel_id: source.channel.id,
    format_key: source.format.key,
    image_base64: imageBase64,
    prompt: source.image_prompt,
    content: {
      headline:
        source.approved_copy?.content?.headline || null,
      primary_text:
        source.approved_copy?.content?.primary_text || null,
      description:
        source.approved_copy?.content?.description || null,
      cta:
        source.approved_copy?.content?.cta || null
    },
    metadata: {
      generator: 'openai-responses-image-generation',
      response_id: response.id || null,
      response_model: response.model || 'gpt-5.4',
      reference_urls: source.reference_urls,
      requested_width: source.format.width,
      requested_height: source.format.height
    },
    output: {
      openai_response_id: response.id || null,
      generated_at: new Date().toISOString()
    }
  }
}];

let source = {};

try {
  source =
    $('Preparar Criativo Visual').first().json;
} catch {}

const incoming = $json || {};
const error =
  incoming.error ||
  incoming.cause ||
  incoming;

const message = String(
  error.message ||
  error.description ||
  error.error?.message ||
  'Falha não identificada na geração da imagem.'
).slice(0, 2000);

if (!source.job?.id) {
  throw new Error(
    'Não foi possível identificar o job visual com falha: ' +
    message
  );
}

return [{
  json: {
    job_id: source.job.id,
    worker_id:
      source.worker_id ||
      'n8n-central-criativos-imagens-v1',
    error_code: 'OPENAI_IMAGE_GENERATION_FAILED',
    error_message: message,
    output: {
      failed_at: new Date().toISOString(),
      format_key: source.format?.key || null,
      details: message
    }
  }
}];
